# xow-win uninstaller (runs elevated; launched by Uninstall-Xbox-Wireless-Driver.cmd)
# Stops the driver, removes the login entry and files, and gives the adapter back
# to Microsoft's driver. ViGEmBus is left installed (other tools may use it).
param(
    [string]$InstallDir = "$env:LOCALAPPDATA\xow-win",
    [string]$StartupDir = "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup",
    [string]$DesktopDir = [Environment]::GetFolderPath('Desktop')
)
$ErrorActionPreference = 'Continue'
function L($m) { Write-Host ((Get-Date -Format 'HH:mm:ss') + '  ' + $m) }

$TaskName = 'xow-win Xbox Wireless Driver'
Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
try { $e = [System.Threading.EventWaitHandle]::OpenExisting('Local\xow-win-stop'); [void]$e.Set(); Start-Sleep 3; [void]$e.Reset(); $e.Close() } catch { }
Get-Process xow-win* -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
L "Driver stopped"

Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue
L "Login task removed"
Remove-Item (Join-Path $StartupDir 'xow-win.vbs') -Force -ErrorAction SilentlyContinue
foreach ($f in 'Xbox-Wireless-Driver.cmd', 'Stop-Xbox-Wireless-Driver.cmd', 'Xbox-Controller-Settings.cmd', 'Reset-Xbox-Adapter.cmd') { Remove-Item (Join-Path $DesktopDir $f) -Force -ErrorAction SilentlyContinue }
Remove-Item $InstallDir -Recurse -Force -ErrorAction SilentlyContinue
L "Login entry, shortcuts and files removed"

# Remove the libwdi WinUSB package; Windows then re-selects Microsoft's driver
$pkg = (& pnputil.exe /enum-drivers) -join "`n" -split "`n`n" | Where-Object { $_ -match 'xbox_acc.inf' }
if ($pkg -and $pkg -match 'Published Name:\s+(oem\d+\.inf)') {
    $oem = $Matches[1]
    L ("Removing WinUSB package {0}: {1}" -f $oem, ((& pnputil.exe /delete-driver $oem /uninstall /force) | Select-String 'success|Failed' | Select-Object -First 1))
    & pnputil.exe /scan-devices | Out-Null
    Start-Sleep 3
    $dev = Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -like 'USB\VID_045E&PID_02E6*' } | Select-Object -First 1
    if ($dev) { L ("Adapter driver service now: " + (Get-PnpDeviceProperty -InstanceId $dev.InstanceId -KeyName 'DEVPKEY_Device_Service').Data) }
} else { L "WinUSB package not found (already removed)" }

foreach ($store in 'Root', 'TrustedPublisher') {
    Get-ChildItem "Cert:\LocalMachine\$store" | Where-Object { $_.Subject -match 'libwdi autogenerated' } | Remove-Item -Force -ErrorAction SilentlyContinue
}
L "libwdi certificate removed"
L "=== uninstall complete (ViGEmBus left installed) ==="
Start-Sleep 5
